package io.knowledgebrain.content;
import java.util.*;import java.time.*;import jakarta.servlet.http.Cookie;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
class RecordConceptApiTest {
 RecordConceptStore store;SpaceAuthorizationClient auth;ConceptAvailabilityClient concepts;RecordConceptsController api;UUID space,source,actor,a,b;RecordConceptStore.View current;
 @BeforeEach void init(){var ids=new UuidV7(Clock.systemUTC());space=ids.next();source=ids.next();actor=ids.next();a=ids.next();b=ids.next();store=mock(RecordConceptStore.class);auth=mock(SpaceAuthorizationClient.class);concepts=mock(ConceptAvailabilityClient.class);api=new RecordConceptsController(store,auth,concepts,new SimpleMeterRegistry(),"https://localhost:8443");when(auth.authorizeBookmark(eq(space),any(),anyBoolean(),anyString())).thenReturn(actor);when(auth.authorizeQuestion(eq(space),any(),anyBoolean(),anyString())).thenReturn(actor);when(auth.authorizeDecision(eq(space),any(),anyBoolean(),anyString())).thenReturn(actor);current=new RecordConceptStore.View(space,RecordConceptStore.Kind.BOOKMARK,source,"ACTIVE",1,new RecordConceptStore.Snapshot(null,0,List.of()));when(store.get(space,RecordConceptStore.Kind.BOOKMARK,source)).thenReturn(current);}
 MockHttpServletRequest request(String method,String body){var r=new MockHttpServletRequest(method,"/");r.setSecure(true);r.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)));r.setContentType("application/json");r.addHeader("Origin","https://localhost:8443");r.addHeader("If-Match","\"rc0\"");r.addHeader("traceparent","00-"+"e".repeat(32)+"-"+"a".repeat(16)+"-01");if(body!=null)r.setContent(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));return r;}
 String body(UUID...ids){return "{\"conceptIds\":["+Arrays.stream(ids).map(v->"\""+v+"\"").collect(java.util.stream.Collectors.joining(","))+"]}";}
 void status(int code,org.junit.jupiter.api.function.Executable fn){assertEquals(code,assertThrows(ResponseStatusException.class,fn).getStatusCode().value());}
 @Test void exactBodiesQueriesOriginsTagsAndSessionsAreEnforcedBeforeMutation()throws Exception{for(String value:List.of("{}","{\"conceptIds\":[],\"conceptIds\":[]}","{\"conceptIds\":[]} {}",body(a,a),"{\"conceptIds\":[\""+UUID.randomUUID()+"\"]}"))status(400,()->api.replace(space.toString(),"BOOKMARK",source.toString(),request("PUT",value)));var missing=request("PUT",body());missing.removeHeader("If-Match");status(428,()->api.replace(space.toString(),"BOOKMARK",source.toString(),missing));for(String tag:List.of("\"bm1\"","W/\"rc0\"","\"rc00\"","*")){var r=request("PUT",body());r.removeHeader("If-Match");r.addHeader("If-Match",tag);status(400,()->api.replace(space.toString(),"BOOKMARK",source.toString(),r));}var origin=request("PUT",body());origin.removeHeader("Origin");status(403,()->api.replace(space.toString(),"BOOKMARK",source.toString(),origin));var cookies=request("GET",null);cookies.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)),new Cookie("__Host-brain_guest","b".repeat(43)));status(401,()->api.get(space.toString(),"BOOKMARK",source.toString(),cookies));status(400,()->api.get(space.toString(),"BOOKMARK",source.toString(),request("GET","{}")));var query=request("GET",null);query.addParameter("limit","1","2");status(400,()->api.history(space.toString(),"BOOKMARK",source.toString(),query));status(413,()->api.replace(space.toString(),"BOOKMARK",source.toString(),request("PUT"," ".repeat(2049))));verifyNoInteractions(store,concepts);}
 @Test void onlyNewTargetsAreCheckedAndStaleVersionsFailBeforeKnowledge()throws Exception{var prior=new RecordConceptStore.View(space,RecordConceptStore.Kind.BOOKMARK,source,"ACTIVE",1,new RecordConceptStore.Snapshot(a,1,List.of(new RecordConceptStore.Link(b,a))));when(store.get(space,RecordConceptStore.Kind.BOOKMARK,source)).thenReturn(prior);status(412,()->api.replace(space.toString(),"BOOKMARK",source.toString(),request("PUT",body(a,b))));verifyNoInteractions(concepts);var r=request("PUT",body(a,b));r.removeHeader("If-Match");r.addHeader("If-Match","\"rc1\"");when(store.replace(eq(space),any(),eq(source),eq(actor),eq(1L),any(),anyString())).thenReturn(prior);api.replace(space.toString(),"BOOKMARK",source.toString(),r);verify(concepts).check(eq(space),eq(List.of(b)),eq("a".repeat(43)),eq("00-"+"e".repeat(32)+"-"+"a".repeat(16)+"-01"));reset(concepts);r=request("PUT",body());r.removeHeader("If-Match");r.addHeader("If-Match","\"rc1\"");api.replace(space.toString(),"BOOKMARK",source.toString(),r);verifyNoInteractions(concepts);}
 @Test void knowledgeFailureAndArchivedSourceCannotMutateAssociations()throws Exception{when(concepts.check(any(),any(),any(),any())).thenThrow(new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE));status(503,()->api.replace(space.toString(),"BOOKMARK",source.toString(),request("PUT",body(a))));verify(store,never()).replace(any(),any(),any(),any(),anyLong(),any(),any());reset(concepts);when(store.get(space,RecordConceptStore.Kind.BOOKMARK,source)).thenReturn(new RecordConceptStore.View(space,RecordConceptStore.Kind.BOOKMARK,source,"RETIRED",2,current.links()));status(404,()->api.replace(space.toString(),"BOOKMARK",source.toString(),request("PUT",body(a))));verifyNoInteractions(concepts);}
 @Test void eachTypeRechecksItsOwnReadWriteCapabilityAndReturnsNoStore()throws Exception{for(var k:RecordConceptStore.Kind.values()){var v=new RecordConceptStore.View(space,k,source,"ACTIVE",1,current.links());when(store.get(space,k,source)).thenReturn(v);var response=api.get(space.toString(),k.name(),source.toString(),request("GET",null));assertEquals("no-store",response.getHeaders().getCacheControl());assertEquals("\"rc0\"",response.getHeaders().getETag());when(store.replace(eq(space),eq(k),eq(source),eq(actor),eq(0L),any(),anyString())).thenReturn(v);api.replace(space.toString(),k.name(),source.toString(),request("PUT",body()));}verify(auth).authorizeBookmark(eq(space),any(),eq(false),anyString());verify(auth).authorizeBookmark(eq(space),any(),eq(true),anyString());verify(auth).authorizeQuestion(eq(space),any(),eq(false),anyString());verify(auth).authorizeQuestion(eq(space),any(),eq(true),anyString());verify(auth).authorizeDecision(eq(space),any(),eq(false),anyString());verify(auth).authorizeDecision(eq(space),any(),eq(true),anyString());verify(auth,never()).authorize(any(),any(),anyBoolean(),any());verifyNoInteractions(concepts);}
}
